import{_ as i,l,o as a,c as t,v as o,p as s,x as r,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"Genie 3 交互世界模型","description":"","frontmatter":{"title":"Genie 3 交互世界模型","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/genie-3.md","filePath":"llm/genie-3.md","lastUpdated":1789023840000}'),h={name:"llm/genie-3.md"};function m(A,e,B,c,f,u){const n=l("Mermaid");return a(),t("div",null,[e[1]||(e[1]=o('<h1 id="genie-3-交互世界模型" tabindex="-1">Genie 3 交互世界模型 <a class="header-anchor" href="#genie-3-交互世界模型" aria-label="Permalink to &quot;Genie 3 交互世界模型&quot;">​</a></h1><div class="epigraph"><p>给定文本提示，即可生成可实时导航的动态世界：约 24 帧每秒，720p，并在数分钟内保持一致性。</p><footer>—— Parker-Holder 与 Fruchter，Genie 3: A new frontier for world models，Google DeepMind，2025-08-05</footer></div><p>DeepMind 在 2025 年 8 月 5 日宣布 <strong>Genie 3</strong>：通用世界模型，从文本生成可探索环境。相对 Genie 1/2（为智能体生成新环境的基础世界模型）与 <a href="/llm/veo-3">Veo</a> 系视频生成，Genie 3 被写成<strong>第一个可实时交互</strong>的世界模型，并提高一致性与真实感。操作定义：自回归地一帧帧生成，每一步要看不断变长的历史轨迹；用户动作以每秒多次的频率进入；回到一分钟前见过的地点时，模型须调用当时的信息。一致性被说成涌现能力，而不是先重建 NeRF 或高斯溅射再渲染。官方同时列出限制：动作空间有限、多主体交互难、真实地点地理不准、文字依赖提示、连续交互约数分钟而非数小时。发布时是有限研究预览。本篇只根据该博客与 Genie 产品页，不引用非官方架构拆解。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>视频生成给出固定时间轴；游戏引擎给出可交互但内容要手工或程序化建好。世界模型要同时满足：从语言（或图像）描述出环境、对用户或智能体动作有反应、在足够长的视界里不自相矛盾。Genie 2 已能生成环境，但实时交互与长程记忆不足。Veo 擅长观感与物理直觉，输出却不是可玩循环。机器人与 SIMA 一类具身智能体需要无限课程的模拟器：环境不能全靠艺术家关卡。问题是：能否在没有显式三维资产的情况下，用帧预测当模拟器，并且快到能闭环。</p><p>DeepMind 把世界模型定义为：用对物理环境的理解去模拟，使智能体预测世界如何演化、自身动作如何改变它，并写成通往 AGI 的台阶之一。这是研究叙事。工程上必须把「模拟」落成可测合同：分辨率、帧率、一致性时长、动作接口。博客给出 720p、24 fps、数分钟。没有公开的参数量、tokenizer 或训练小时。比较 <a href="/llm/cosmos-world-model">Cosmos</a> 时：Cosmos 平台论文把 WFM 写成可后训练的视频预测器并开部分权重；Genie 3 是闭源研究预览加后来的产品原型入口，不要把 Cosmos 的 tokenizer 表填进 Genie。</p><h3 id="一致性来自帧生成-不是来自冻结网格" tabindex="-1">一致性来自帧生成，不是来自冻结网格 <a class="header-anchor" href="#一致性来自帧生成-不是来自冻结网格" aria-label="Permalink to &quot;一致性来自帧生成，不是来自冻结网格&quot;">​</a></h3><p>博客对比：NeRF、高斯溅射等提供可导航一致性，但依赖显式三维表示，动态丰富度受限。Genie 3 按世界描述与用户动作逐帧生成，环境可以更动态（水、光、天气、生物），一致性是学出来的，会在长时与回视时失败。回视是核心难题：轨迹变长，实时性要求每秒多次把整段历史算进去。这与离线生成一段 5 秒视频的计算图不同——后者可以一次看全片段，前者必须在动作到达时给出下一帧。</p><p><span class="marginnote">产品页另写约 20–24 fps 的流畅交互。博客正文用 24 fps 与 720p。Project Genie 等后续入口以当时 Google 公告为准，不把 2026 年的订阅包装倒填进 2025-08-05 这篇研究发布。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>公开能力列表。物理与自然现象：水、光照、复杂地形与天气。生态系统：动植物行为。导航：第一人称或载具视角在生成世界中移动。<strong>Promptable world events</strong>：除方向键一类导航外，用文本改变世界（天气、加入物体或角色），增加反事实「若当时……」的干预，供智能体从经验学习意外。具身研究：把世界交给 SIMA 一类通用 3D 智能体，智能体发导航动作，Genie 3 <strong>不知道</strong>智能体的语言目标，只根据动作模拟未来——与普通环境接口相同。</p><p>责任：开放式实时生成带来新风险，官方称与 Responsible Development 团队合作，并以小范围学术与创作者预览收集反馈。限制节应与能力节成对引用，避免只剪样片。后续 DeepMind 写过扩大测试；本篇机制以 8 月 5 日文为准。</p>',12)),(a(),s(E,null,{default:r(()=>[d(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%E4%B8%96%E7%95%8C%E6%8F%8F%E8%BF%B0%22%5D%20--%3E%20W%5B%22Genie%203%20%E4%B8%96%E7%95%8C%E7%8A%B6%E6%80%81%EF%BC%88%E9%9A%90%E5%BC%8F%EF%BC%89%22%5D%0A%20%20ACT%5B%22%E5%AF%BC%E8%88%AA%E5%8A%A8%E4%BD%9C%22%5D%20--%3E%20W%0A%20%20EVT%5B%22%E5%8F%AF%E6%8F%90%E7%A4%BA%E4%B8%96%E7%95%8C%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20W%0A%20%20W%20--%3E%20F%5B%22%E8%87%AA%E5%9B%9E%E5%BD%92%E4%B8%8B%E4%B8%80%E5%B8%A7%20720p%22%5D%0A%20%20F%20--%3E%20HIST%5B%22%E8%BD%A8%E8%BF%B9%E5%8E%86%E5%8F%B2%22%5D%0A%20%20HIST%20--%3E%20W%0A%20%20F%20--%3E%20USER%5B%22%E5%AE%9E%E6%97%B6%E6%98%BE%E7%A4%BA%20~24fps%22%5D%0A%20%20AGENT%5B%22%E5%85%B7%E8%BA%AB%E6%99%BA%E8%83%BD%E4%BD%93%22%5D%20--%3E%20ACT%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="可提示事件不是智能体的身体动作" tabindex="-1">可提示事件不是智能体的身体动作 <a class="header-anchor" href="#可提示事件不是智能体的身体动作" aria-label="Permalink to &quot;可提示事件不是智能体的身体动作&quot;">​</a></h3><p>博客区分：导航由用户或 SIMA 发出；天气与物体出现等事件是文本干预，<strong>不一定由智能体自己的身体完成</strong>。因此「动作空间有限」与「事件很炫」可以同时为真。评测具身能力时，应看智能体可发的原子动作是否足够完成目标，而不是看演示者键入了一句换天气。把事件当成已经拥有全能身体，会高估可训练性。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是条件帧预测：条件包括初始描述、过去帧（及其中的外观记忆）、最新动作与可选文本事件。实时性把计算预算钉在几十毫秒级的帧间隔上，历史变长则记忆与注意必须压缩或选择性回顾——博客只陈述「必须回头看一分钟前」，不给记忆模块图。涌现一致性意味着没有单独的碰撞网格；穿模与物体消失会以像素错误出现，而不是引擎报错。对智能体训练，这既是优点（无需建关）也是缺点（奖励与重置函数要对着像素定义，状态不可查询）。</p><p>与文生视频的差别：Sora / Veo 优化整段观感，观众不中途改轨迹。Genie 3 的观众是控制器，错误会在闭环里被下一步动作放大。与 Cosmos 的差别：Cosmos 强调物理 AI 后训练接口与护栏流水线；Genie 3 强调可玩多样性与实时。两者都不要写成已验证的机器人策略训练平台——Genie 文对 SIMA 是兼容性测试叙事。</p><p><span class="marginnote">官方限制：多独立智能体共享环境仍是开放问题；真实地名不能当地图用；清晰文字往往需要写进世界描述。把旅行模拟当成地理信息系统，会超出博客主张。</span></p><h3 id="数分钟视界决定它还不是持久宇宙" tabindex="-1">数分钟视界决定它还不是持久宇宙 <a class="header-anchor" href="#数分钟视界决定它还不是持久宇宙" aria-label="Permalink to &quot;数分钟视界决定它还不是持久宇宙&quot;">​</a></h3><p>「数分钟」是合同：够演示与短课程，不够开放世界网游或长时机器人班次。超时后的世界是否可序列化，博客未作为产品保证。教育与培训被列为可能用途，前提是内容安全与真实地点限制。预览策略说明：能力足够新，发布形态不是全面开放 API。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><h3 id="研究预览的数字不要当-sla" tabindex="-1">研究预览的数字不要当 SLA <a class="header-anchor" href="#研究预览的数字不要当-sla" aria-label="Permalink to &quot;研究预览的数字不要当 SLA&quot;">​</a></h3><p>24 fps 与 720p 是宣布时的能力描述，不是多地区生产配额。访问名单、安全过滤、是否记录会话，以当时条款为准。不要推测训练数据。与 <a href="/llm/sora-2">Sora 2</a> 比较：一个产出可分享的带声短片，一个产出可玩的无声或弱声（博客未把原生电影级音轨写成主轴）交互视口——音频合同以当时页面为准，未写则不要发明。</p><p>本篇不讨论如何用生成世界规避现实法规或伪造实时新闻现场。责任节已把开放式生成列为需额外缓解的类别。引用用 DeepMind 博客 BibTeX 所指向的该文。</p><p><span class="marginnote">出处：Parker-Holder &amp; Fruchter，<em>Genie 3: A new frontier for world models</em>，Google DeepMind，2025-08-05；能力列表对照 deepmind.google/models/genie。仅公开博客。对照 Genie 1/2 与 Veo 的官方世界模拟分工。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Genie 3 从文本生成可实时导航的世界，官方口径约 24 fps、720p、数分钟一致性。</li><li>逐帧自回归加动作条件；一致性是学出来的，不是显式三维引擎。</li><li>可提示世界事件补充导航；SIMA 测试把世界当未知目标的环境。</li><li>限制与预览范围与能力同样是规格的一部分。</li><li>出处：DeepMind Genie 3 博客，2025-08-05。</li></ul>',15))])}const G=i(h,[["render",m]]);export{g as __pageData,G as default};
